"use client";
import { useEffect, useState, type FormEvent } from "react";
import { ArrowLeft, BriefcaseBusiness, CalendarDays, CheckCircle2, ChevronLeft, Clock3, FileText, Heart, LoaderCircle, MapPin, Search, ShieldCheck, Sparkles, Upload, Users, Waves } from "lucide-react";
import { apiRequest, connectionError } from "@/lib/api-client";
import { Field, Modal, EmptyState } from "@/components/ui";
import { dateFa, departments, fa, money } from "@/lib/types";
import type { Job } from "@/lib/talent-types";
export default function CareersPage() {
  const [jobs, setJobs] = useState<Job[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [selected, setSelected] = useState<Job | null>(null); const [department, setDepartment] = useState("all"); const [query, setQuery] = useState(""); const [version, setVersion] = useState(0);
  useEffect(() => { const c = new AbortController(); setLoading(true); setError(""); apiRequest<{ jobs: Job[] }>("/api/careers", { signal: c.signal }).then(r => setJobs(r.jobs)).catch(e => { if (!c.signal.aborted) setError(connectionError(e).message); }).finally(() => { if (!c.signal.aborted) setLoading(false); }); return () => c.abort(); }, [version]);
  const filtered = jobs.filter(j => (department === "all" || j.department === department) && `${j.title} ${j.description}`.includes(query));
  return <div className="careers-page"><header className="careers-header"><a className="careers-logo" href="/careers"><span><Waves size={28} /></span><strong>آبان<small>فرصت‌های همکاری</small></strong></a><a className="btn secondary" href="/login">ورود همکاران<ArrowLeft size={15} /></a></header><main><section className="careers-hero"><img src="/images/waterpark.jpg" alt="نمای پارک آبی" /><div><span><Sparkles size={13} />همراه ما، در جریان حال خوب</span><h1>جای شما در تیم آبان خالی است.</h1><p>برای ساختن تجربه‌های خوش، به آدم‌های همراه نیاز داریم.<br />فرصت مناسب خود را پیدا کنید و فصل تازه‌ای از همکاری را آغاز کنید.</p><a href="#opportunities">فرصت‌های همکاری<ArrowLeft size={16} /></a></div></section><section className="careers-values"><div><Users size={24} /><strong>یک تیم همراه</strong><p>احترام متقابل و همکاری واقعی</p></div><div><Sparkles size={24} /><strong>فرصتی برای رشد</strong><p>آموزش و همراهی از اولین روز</p></div><div><Heart size={24} /><strong>حال خوب در محیط کار</strong><p>تجربه‌ای انسانی و مسئولانه</p></div></section><section className="careers-jobs" id="opportunities"><div className="tl-section-head"><div><span className="eyebrow">شاید شروع بعدی شما همین‌جا باشد</span><h2>فرصت‌های باز تیم آبان</h2></div><span className="count-pill">{fa(jobs.length)} فرصت همکاری</span></div><div className="tl-toolbar"><div className="input-search"><Search size={17} /><input aria-label="جستجوی فرصت شغلی" value={query} onChange={e => setQuery(e.target.value)} placeholder="عنوان شغلی مورد نظر شما..." /></div><select aria-label="فیلتر واحد" value={department} onChange={e => setDepartment(e.target.value)}><option value="all">همه واحدها</option>{departments.map(d => <option key={d}>{d}</option>)}</select></div>{loading ? <div className="talent-loading"><LoaderCircle className="spin" size={26} /><p>در حال دریافت فرصت‌های همکاری...</p></div> : error ? <EmptyState title="فرصت‌ها دریافت نشدند" description={error} action="تلاش دوباره" onAction={() => setVersion(v => v + 1)} /> : filtered.length ? <div className="careers-job-list">{filtered.map(j => <button className="careers-job-row" key={j.id} onClick={() => setSelected(j)}><span className="tl-module-icon teal"><BriefcaseBusiness size={25} /></span><div><h3>{j.title}</h3><p>{j.department}</p><div><span><MapPin size={13} />{j.location}</span><span><Clock3 size={13} />{j.contract}</span><span><Users size={13} />{fa(j.openings)} نفر</span></div></div><span className="careers-job-apply">مشاهده و ارسال درخواست<ArrowLeft size={17} /></span></button>)}</div> : <EmptyState title="در حال حاضر فرصتی با این مشخصات نداریم" description="فیلترها را تغییر دهید یا در روزهای آینده دوباره سر بزنید." />}</section><div className="careers-privacy"><ShieldCheck size={20} /><p>اطلاعات درخواست شما فقط برای بررسی همکاری در اختیار تیم جذب مجاز قرار می‌گیرد. هیچ رزومه‌ای به سرویس بیرونی ارسال نمی‌شود. این محیط نمایشی است؛ از اطلاعات شخصی واقعی استفاده نکنید.</p></div></main><footer className="careers-footer"><Waves size={20} /><span>آبان؛ همراه تیم شما در هر موج</span><a href="/login">پنل همکاران<ChevronLeft size={13} /></a></footer>{selected && <ApplicationDialog job={selected} close={() => setSelected(null)} />}</div>;
}
function ApplicationDialog({ job, close }: { job: Job; close: () => void }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [result, setResult] = useState(""); const [filename, setFilename] = useState("");
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); if (busy) return; const form = new FormData(e.currentTarget); form.set("jobId", job.id); setBusy(true); setError(""); try { const result = await apiRequest<{ trackingCode: string }>("/api/careers", { method: "POST", body: form }); setResult(result.trackingCode); } catch (e) { setError(connectionError(e).message); } finally { setBusy(false); } }
  return <Modal title={result ? "درخواست شما به تیم جذب رسید" : job.title} subtitle={job.department} onClose={() => { if (!busy) close(); }} wide>{result ? <><div className="import-success"><div><CheckCircle2 size={40} /></div><h2>برای شروع این آشنایی ممنونیم</h2><p>درخواست شما ثبت شد و پس از بررسی سوابق، تیم جذب برای هماهنگی مراحل بعدی از اطلاعات تماس ارائه‌شده استفاده خواهد کرد.</p><span className="careers-tracking" dir="ltr">AB-{result}</span><small>کد ثبت درخواست را نزد خود نگه دارید.</small></div><div className="modal-footer"><button className="btn primary" onClick={close}>بازگشت به فرصت‌ها</button></div></> : <form onSubmit={submit}><div className="modal-body tl-detail"><div className="tl-job-meta"><span><MapPin size={14} />{job.location}</span><span><Clock3 size={14} />{job.contract}</span><span><CalendarDays size={14} />تا {dateFa(job.deadline)}</span></div><div className="tl-detail-section"><h3>درباره این همکاری</h3><p className="tl-welcome-text">{job.description}</p><h3>آنچه برای این نقش نیاز دارید</h3><p className="tl-welcome-text">{job.requirements}</p>{job.salaryMax > 0 && <span className="badge green">بازه حقوق: {fa(job.salaryMin)} تا {money(job.salaryMax)}</span>}</div><SectionLine /><div className="form-grid"><Field label="نام و نام خانوادگی"><input name="name" required maxLength={150} /></Field><Field label="نشانی ایمیل"><input name="email" type="email" required maxLength={254} dir="ltr" /></Field><Field label="شماره تماس"><input name="phone" type="tel" required maxLength={30} dir="ltr" /></Field><Field label="سابقه مرتبط (سال)"><input name="experience" type="number" min={0} max={50} defaultValue={0} required /></Field><Field label="مهارت‌های مرتبط" className="tl-wide"><input name="skills" maxLength={2000} /></Field><Field label="کمی از خودتان بگویید" className="tl-wide"><textarea name="summary" rows={3} maxLength={5000} /></Field><Field label="رزومه PDF (اختیاری)" hint="حداکثر ۲ مگابایت؛ فایل در پایگاه داده ذخیره می‌شود." className="tl-wide"><input name="file" type="file" accept=".pdf" onChange={e => setFilename(e.target.files?.[0]?.name || "")} />{filename && <small>{filename}</small>}</Field></div><input name="website" autoComplete="off" tabIndex={-1} className="careers-honeypot" aria-hidden="true" /><label className="tl-consent"><input required type="checkbox" name="consent" value="true" /><span>با نگهداری و پردازش اطلاعاتم صرفاً برای بررسی درخواست استخدام در آبان موافقم.</span></label>{error && <div className="inline-error" role="alert">{error}</div>}</div><div className="modal-footer"><button className="btn secondary" type="button" onClick={close} disabled={busy}>بازگشت</button><button className="btn primary" type="submit" disabled={busy}>{busy ? <LoaderCircle size={16} className="spin" /> : <ArrowLeft size={16} />}{busy ? "در حال ارسال..." : "ارسال درخواست همکاری"}</button></div></form>}</Modal>;
}
function SectionLine() { return <div className="form-section-label"><FileText size={16} />اطلاعات درخواست همکاری</div>; }
